<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include<bits/stdc++.h>
#define fr(i,a,b) for(int i(a),end##i(b);i<=end##i;i++)
#define fd(i,a,b) for(int i(a),end##i(b);i>=end##i;i--)
using namespace std;
const int maxn=2.7e5+5;
int m,n,k;
int mod;
int f[19][maxn];
vector<long long> g;
int cnt[maxn];
int upd(const int &x){
	if(x<0)return x+mod;
	if(x>=mod)return x-mod;
	return x;
}
void add(int &x,const int &y){
	x=upd(x+y);
}
int ksm(int x,int k){
	int ans=1;
	while(k){
		if(k&1)ans=1ll*ans*x%mod;
		x=1ll*x*x%mod;
		k>>=1;
	}
	return ans;
}
int jc[maxn],inv[maxn];
void init(int n){
	jc[0]=1;
	fr(i,1,n)jc[i]=1ll*jc[i-1]*i%mod;
	inv[n]=ksm(jc[n],mod-2);
	fd(i,n-1,0)inv[i]=1ll*inv[i+1]*(i+1)%mod;
}
void F(int *f,int n,int h){
	for(int p=1;p<n;p<<=1)
		for(int i=0;i<n;i+=p<<1)fr(k,i,i+p-1){
			add(f[k+p],h*f[k]);		
		}
}
int l;
vector<long long> operator *(vector<long long> &A,vector<long long> &B){
	static vector<long long> C;C.clear();C.resize(l+1);
	fr(i,0,l)fr(j,0,l-i)C[i+j]+=A[i]*B[j];
	fr(i,0,l)C[i]%=mod;
	return C;	
}
vector<long long> pksm(vector<long long> A,int k){
	static vector<long long> C;C.clear();C.resize(l+1);
	C[0]=1;
	while(k){
		if(k&1)C=C*A;
		A=A*A;
		k>>=1;
	}
	return C;
}
int main(){
#ifdef pig
	freopen("C.in","r",stdin);
	freopen("C.out","w",stdout);
#endif
	cin>>n>>k>>mod;
	init(n);
	if(n&1){
		cout<<ksm(k,n);
		return 0;
	}
	m=1;while(m<=n)m<<=1,l++;
	fr(i,0,m-1)cnt[i]=cnt[i>>1]+(i&1);
	init(m);
	fr(i,0,m-1){	
		f[cnt[i]][i]=inv[i];		
	}
	fr(i,0,l)F(f[i],m,1);
	g.resize(l+1);
	fr(s,0,m-1){
		fr(i,0,l)g[i]=f[i][s];
		g=pksm(g,k);
		fr(i,0,l)f[i][s]=g[i];
	}
	F(f[cnt[n]],m,-1);
	cout<<upd(ksm(k,n)-1ll*f[cnt[n]][n]*jc[n]%mod);
	return 0;
}

